458      private static FType narrowest(String n, List<FValue> vals,
459                                     BoundingMap<String, FType, TypeLatticeOps> abm,
460                                     List<StaticParam> rechecks, Set<String> tp_set, Environment env,
461                                     List<FType> bounds, Environment within, boolean supertypes) {
462          LinkedHashSet<FType> candidates = new LinkedHashSet<FType>();
463          for (FValue v : vals) {
464              if (supertypes) candidates.addAll(v.type().getTransitiveExtends());
465              else candidates.add(v.type());
466          }
467          for (FValue v : vals) candidates.addAll(Coercions.coercionTargets(v, within));
468          if (bounds != null) candidates.addAll(bounds);
469          List<FType> admitted = new ArrayList<FType>();
470          for (FType c : candidates) {
471              if (c instanceof BottomType || c instanceof FTypeTop) continue;
472              boolean all = true;
473              for (FValue v : vals) {
474                  if (!Coercions.admits(c, v)) {
475                      all = false;
476                      break;
477                  }
478              }
479              if (!all) continue;
480              BoundingMap<String, FType, TypeLatticeOps> trial = abm.copy();
481              try {
482                  trial.joinPut(n, c);
483                  for (StaticParam tp : rechecks) {
484                      if (!NodeUtil.getName(tp).equals(n)) continue;
485                      for (Type tr : tp.getExtendsClause()) c.unify(env, tp_set, trial, tr);
486                  }
487              }
488              catch (FortressException ex) {
489                  continue;
490              }
491              catch (EmptyLatticeIntervalError ex) {
492                  continue;
493              }
494              admitted.add(c);
495          }
496          FType best = null;
497          for (FType c : admitted) {
498              boolean narrower = true;
499              for (FType d : admitted) {
500                  if (d != c && !c.subtypeOf(d) && !Coercions.convertsInto(c, d)) {
501                      narrower = false;
502                      break;
503                  }
504              }
505              if (narrower) {
506                  if (best != null && best != c) return null;
507                  best = c;
508              }
509          }
510          return best;
511      }

